const express = require('express');
const crypto = require('crypto');
const url = require('url');
const { URL } = require('url');

const app = express();

// CI/CD Pipeline OAuth callback handler for Kubernetes deployment service
const ALLOWED_REDIRECT_ORIGINS = [
  'https://ci.internal.corp.io',
  'https://deploy.internal.corp.io',
  'https://pipeline.internal.corp.io'
];

const OAUTH_CLIENT_ID = process.env.OAUTH_CLIENT_ID || 'cicd-pipeline-controller';
const OAUTH_SECRET = process.env.OAUTH_SECRET || crypto.randomBytes(32).toString('hex');
const STATE_STORE = new Map();

function generateState(sessionId, redirectUri) {
  const nonce = crypto.randomBytes(16).toString('hex');
  const stateToken = crypto.createHmac('sha256', OAUTH_SECRET)
    .update(`${sessionId}:${nonce}`)
    .digest('hex');
  STATE_STORE.set(stateToken, { sessionId, redirectUri, createdAt: Date.now(), nonce });
  return stateToken;
}

function validateState(stateToken, sessionId) {
  const entry = STATE_STORE.get(stateToken);
  if (!entry) return null;
  if (Date.now() - entry.createdAt > 300000) {
    STATE_STORE.delete(stateToken);
    return null;
  }
  if (entry.sessionId !== sessionId) return null;
  STATE_STORE.delete(stateToken);
  return entry;
}

function normalizeRedirectUri(inputUri) {
  try {
    const parsed = new URL(inputUri);
    // Strip fragments and normalize
    parsed.hash = '';
    // Normalize path by resolving dot segments
    const normalizedPath = parsed.pathname.split('/').reduce((acc, segment) => {
      if (segment === '..') acc.pop();
      else if (segment !== '.' && segment !== '') acc.push(segment);
      return acc;
    }, []);
    parsed.pathname = '/' + normalizedPath.join('/');
    return parsed;
  } catch (e) {
    return null;
  }
}

function isAllowedRedirect(redirectUri) {
  const normalized = normalizeRedirectUri(redirectUri);
  if (!normalized) return false;

  const targetOrigin = normalized.origin;

  for (const allowed of ALLOWED_REDIRECT_ORIGINS) {
    if (targetOrigin === allowed) return true;
  }
  return false;
}

function extractOriginForValidation(redirectUri) {
  try {
    const parsed = new URL(redirectUri);
    return `${parsed.protocol}//${parsed.hostname}${parsed.port ? ':' + parsed.port : ''}`;
  } catch (e) {
    return null;
  }
}

// Middleware: validate pipeline service token from K8s service account
function validateServiceToken(req, res, next) {
  const token = req.headers['x-pipeline-token'];
  if (!token) return res.status(401).json({ error: 'Missing service token' });
  // In production, validates against K8s TokenReview API
  // Simplified for this component
  try {
    const decoded = Buffer.from(token, 'base64').toString();
    const [svc, namespace] = decoded.split(':');
    if (namespace === 'cicd-system' || namespace === 'pipeline-controllers') {
      req.serviceIdentity = { service: svc, namespace };
      return next();
    }
  } catch (e) {}
  return res.status(403).json({ error: 'Invalid service token' });
}

// Initiate OAuth flow for pipeline deployment authorization
app.get('/auth/start', validateServiceToken, (req, res) => {
  const { redirect_uri, session_id } = req.query;

  if (!redirect_uri || !session_id) {
    return res.status(400).json({ error: 'Missing required parameters' });
  }

  if (!isAllowedRedirect(redirect_uri)) {
    return res.status(403).json({ error: 'Redirect URI not in allowlist' });
  }

  const state = generateState(session_id, redirect_uri);
  const authUrl = `https://idp.corp.io/authorize?client_id=${OAUTH_CLIENT_ID}&state=${state}&redirect_uri=${encodeURIComponent(redirect_uri)}`;

  res.json({ auth_url: authUrl, state });
});

// OAuth callback - processes the authorization code
app.get('/auth/callback', (req, res) => {
  const { code, state, session_id } = req.query;

  if (!code || !state || !session_id) {
    return res.status(400).json({ error: 'Missing callback parameters' });
  }

  const stateEntry = validateState(state, session_id);
  if (!stateEntry) {
    return res.status(403).json({ error: 'Invalid or expired state' });
  }

  // The redirect_uri from the original state entry is used for the final redirect
  // Re-validate before redirecting (defense in depth)
  const finalRedirect = stateEntry.redirectUri;
  const validationOrigin = extractOriginForValidation(finalRedirect);

  if (!ALLOWED_REDIRECT_ORIGINS.includes(validationOrigin)) {
    return res.status(403).json({ error: 'Redirect origin validation failed' });
  }

  // Construct final redirect with auth code for the pipeline
  const redirectTarget = new URL(finalRedirect);
  redirectTarget.searchParams.set('code', code);
  redirectTarget.searchParams.set('pipeline_auth', 'complete');

  res.redirect(302, redirectTarget.toString());
});

// Health check for K8s liveness probe
app.get('/healthz', (req, res) => res.status(200).send('ok'));

const PORT = process.env.PORT || 8443;
app.listen(PORT, '0.0.0.0', () => {
  console.log(`Pipeline OAuth handler listening on ${PORT}`);
});

module.exports = app;
